import assert from 'node:assert/strict';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { readFile } from 'node:fs/promises';
import { request as httpRequest } from 'node:http';
import { request as httpsRequest } from 'node:https';
import { connect } from 'node:net';
import { installLocal } from '../../scripts/install-local.mjs';
import { reviewFixture, reviewNow } from './review.mjs';
import { prepareInsightReview } from '../../src/node/review-evidence.mjs';
import { finalizeInsightReview, analyzeInsights } from '../../src/node/review-insights.mjs';
for (const attempt of [() => fetch('https://example.com'), () => httpRequest('http://example.com'), () => httpsRequest('https://example.com'), () => connect(443, 'example.com')]) assert.throws(attempt, /Network disabled/);
assert.equal(globalThis.blockedNetworkAttempts, 4); globalThis.blockedNetworkAttempts = 0;
const destination = path.join(process.argv[2], 'installed');
await installLocal({ destination });
const { bundledBenchmarkLookup } = await import(pathToFileURL(path.join(destination, 'src/core/benchmark-reference.mjs')));
assert.equal(bundledBenchmarkLookup.select([{ modelId: 'gpt-4.1' }]).entries[0].score, 52.4);
assert.match(await readFile(path.join(destination, 'licenses/aider-Apache-2.0.txt'), 'utf8'), /Apache License/);
const f = reviewFixture(); f.user('one'); f.call('one', 'one', { model: 'gpt-4.1' });
const snapshot = await prepareInsightReview(f.scan(), { range: 'all' }, reviewNow);
await finalizeInsightReview(snapshot, false);
assert.match(snapshot.preview, /aider-gpt41-20250414/);
await analyzeInsights(snapshot, { send: async text => { assert.equal(text, snapshot.preview); return JSON.stringify({ cards: [], emptyReason: 'Fixture', followUp: null }); } });
assert.equal(globalThis.blockedNetworkAttempts, 0);
console.log('Offline benchmark integration passed');
